+
+      .option:hover {
+        border-color: var(--primary);
+        transform: translateY(-1px);
+      }
+
+      .option:focus-within {
+        outline: 3px solid var(--ring);
+        outline-offset: 2px;
+      }
+
+      .option input {
+        inline-size: 1.2rem;
+        block-size: 1.2rem;
+        margin: 0;
+        accent-color: var(--primary);
