+
+        .card,
+        .option,
+        .button {
+          border: 1px solid ButtonText;
+          background: Canvas;
+          box-shadow: none;
+        }
+
+        .button {
+          color: ButtonText;
+        }
+
+        .eyebrow {
+          border: 1px solid ButtonText;
+          background: Canvas;
+          color: CanvasText;
+        }
+      }
+    </style>
+  </head>
+  <body>
