+                <p id="form-status" class="status" aria-live="polite"></p>
+              </div>
+            </form>
+          </section>
+        `;
+      }
+
+      function App() {
+        return PageShell(PreferencesForm());
+      }
+
+      const root = document.getElementById("root");
