  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f6fb;
        --panel: #ffffff;
        --panel-border: #d9e2f0;
        --text: #142033;
        --muted: #5a6780;
        --primary: #345ff6;
        --primary-strong: #2749c8;
        --ring: #8fb0ff;
        --option-bg: #f8faff;
        --option-border: #cbd8ee;
        --shadow: 0 20px 60px rgba(20, 32, 51, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(52, 95, 246, 0.12), transparent 30%),
          linear-gradient(180deg, #f7f9fd 0%, var(--bg) 100%);
        color: var(--text);
      }

      .page {
        width: min(100%, 960px);
        margin: 0 auto;
        padding: 32px 20px 56px;
      }

      .hero {
        margin-bottom: 24px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        padding: 6px 12px;
        border-radius: 999px;
        background: rgba(52, 95, 246, 0.1);
        color: var(--primary-strong);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 16px 0 12px;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 1.05;
      }

      .hero p {
        margin: 0;
        max-width: 42rem;
        font-size: 1.0625rem;
        line-height: 1.6;
        color: var(--muted);
      }

      .card {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        padding: 28px;
        box-shadow: var(--shadow);
      }

      .section-title {
        margin: 0 0 8px;
        font-size: 1.375rem;
      }

      .section-copy {
        margin: 0 0 24px;
        color: var(--muted);
        line-height: 1.6;
      }

      .form-field {
        margin-bottom: 24px;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        margin-bottom: 14px;
        font-size: 1.0625rem;
        font-weight: 700;
      }

      .option-list {
        display: grid;
        gap: 12px;
      }

      .option {
        position: relative;
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 16px 18px;
        border: 1px solid var(--option-border);
        border-radius: 18px;
        background: var(--option-bg);
        cursor: pointer;
        transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
      }

      .option:hover {
        border-color: var(--primary);
        transform: translateY(-1px);
      }

      .option:focus-within {
        outline: 3px solid var(--ring);
        outline-offset: 2px;
      }

      .option input {
        inline-size: 1.2rem;
        block-size: 1.2rem;
        margin: 0;
        accent-color: var(--primary);
      }

      .option-label {
        font-weight: 600;
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 16px;
        flex-wrap: wrap;
      }

      .button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        background: linear-gradient(135deg, var(--primary) 0%, var(--primary-strong) 100%);
        color: #ffffff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(52, 95, 246, 0.28);
      }

      .button:hover {
        filter: brightness(1.02);
      }

      .button:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

      .status {
        margin: 0;
        color: var(--muted);
        font-weight: 600;
      }

      @media (max-width: 640px) {
        .card {
          padding: 22px;
          border-radius: 20px;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
          color: CanvasText;
        }

        .card,
        .option,
        .button {
          border: 1px solid ButtonText;
          background: Canvas;
          box-shadow: none;
        }

        .button {
          color: ButtonText;
        }

        .eyebrow {
          border: 1px solid ButtonText;
          background: Canvas;
          color: CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>
    <script>
      function PageShell(content) {
        return `
          <main class="page">
            <section class="hero">
              <span class="eyebrow">Product settings</span>
              <h1>Choose how you'd like to stay updated</h1>
              <p>
                Set a preferred notification channel for account alerts and product updates.
              </p>
            </section>
            ${content}
          </main>
        `;
      }

      function NotificationOptions() {
        return `
          <div class="form-field">
            <fieldset>
              <legend>How do you prefer to receive notifications?</legend>
              <div class="option-list">
                ${RadioOption("email", "Email", true)}
                ${RadioOption("sms", "SMS")}
                ${RadioOption("push", "Push Notifications")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function RadioOption(value, label, required) {
        return `
          <label class="option" for="${value}">
            <input
              type="radio"
              id="${value}"
              name="notificationPreference"
              value="${label}"
              ${required ? "required" : ""}
            />
            <span class="option-label">${label}</span>
          </label>
        `;
      }

      function PreferencesForm() {
        return `
          <section class="card" aria-labelledby="form-title">
            <h2 id="form-title" class="section-title">Notification preference</h2>
            <p class="section-copy">
              Pick one option below, then submit your selection.
            </p>
            <form id="preferences-form">
              ${NotificationOptions()}
              <div class="actions">
                <button class="button" type="submit">Submit</button>
                <p id="form-status" class="status" aria-live="polite"></p>
              </div>
            </form>
          </section>
        `;
      }

      function App() {
        return PageShell(PreferencesForm());
      }

      const root = document.getElementById("root");
      root.innerHTML = App();

      const form = document.getElementById("preferences-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", function (event) {
        event.preventDefault();

        const data = new FormData(form);
        const preference = data.get("notificationPreference");
        status.textContent = preference
          ? `Preference saved: ${preference}.`
          : "Please select one notification method.";
      });
    </script>
  </body>
</html>
