         outline: 3px solid var(--ring);
         outline-offset: 3px;
       }

       .status {
         margin: 0;
         color: var(--muted);
         font-weight: 600;
       }

       @media (max-width: 640px) {
         .card {
           padding: 22px;
           border-radius: 20px;
         }
       }

       @media (forced-colors: active) {
         body {
           background: Canvas;
           color: CanvasText;
         }

         .card,
         .option,
         .button {
           border: 1px solid ButtonText;
           background: Canvas;
           box-shadow: none;
         }

         .button {
           color: ButtonText;
         }

         .eyebrow {
           border: 1px solid ButtonText;
           background: Canvas;
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>
     <script>
       function PageShell(content) {
         return `
           <main class="page">
             <section class="hero">
               <span class="eyebrow">Product settings</span>
               <h1>Choose how you'd like to stay updated</h1>
               <p>
                 Set a preferred notification channel for account alerts and product updates.
               </p>
             </section>
             ${content}
           </main>
         `;
       }

       function NotificationOptions() {
         return `
           <div class="form-field">
             <fieldset>
               <legend>How do you prefer to receive notifications?</legend>
               <div class="option-list">
                 ${RadioOption("email", "Email", true)}
                 ${RadioOption("sms", "SMS")}
                 ${RadioOption("push", "Push Notifications")}
               </div>
             </fieldset>
           </div>
         `;
       }

       function RadioOption(value, label, required) {
         return `
           <label class="option" for="${value}">
             <input
               type="radio"
               id="${value}"
               name="notificationPreference"
               value="${label}"
               ${required ? "required" : ""}
             />
             <span class="option-label">${label}</span>
           </label>
         `;
       }
')
